// Proposed Chorus role assignments and model-family diversity facts surfaced
// at Checkpoint 2. Role, model, and workspace scope assignments are Chorus
// coordination proposals and do not prove agent launch or replace OS process
// and workspace isolation.
type SwarmPlanItem struct {
	// Roster configuration status.
	Status string
	// Deterministic role assignments when status is configured.
	Assignments []*SwarmRoleItem
	// True if and only if status is configured and the reviewer model family is
	// disjoint from every assigned builder model family.
	CrossFamilyReview bool
	// True if and only if status is configured, an eval_author role is assigned,
	// and the eval_author model family is disjoint from every assigned builder
	// model family.
	CrossFamilyEval bool
	// True when status is configured and all assigned roles share one model family.
	SingleFamily bool
	// Requested roles lacking an authenticated capable profile when status is
	// unconfigured (with builder scopes supplied) or missing_capability; omitted
	// on solo previews with no builder scopes.
	MissingRoles []string
	// Plain-English summary of the proposed swarm roster and model-family posture.
	Summary string
	// Formatted Chorus collaboration manifest text when status is configured; does
	// not claim publication until sent via Chorus.
	Manifest *string
}

// Proposed Chorus agent role assignment derived from server-owned provider
// profiles and explicit workspace scopes. Owned paths and access modes are
// operator-declared coordination ownership boundaries for Chorus agents, not
// Surla-enforced OS isolation.
type SwarmRoleItem struct {
	// Deterministic Chorus agent handle (without leading '@', at most 32
	// characters).
	Handle string
	// Assigned swarm role kind.
	Role string
	// Human-readable scope label for this assignment.
	ScopeName string
	// Assigned server-configured provider profile ID.
	ProfileID string
	// Assigned coding-agent provider name.
	Provider string
	// Assigned model identifier.
	Model string
	// Canonical model family identifier.
	Family string
	// Repository or workspace path globs owned by this role for Chorus
	// coordination.
	OwnedPaths []string
	// Operator-declared workspace coordination boundary for this role.
	AccessMode string
}

// Evaluated Goa-AI tool contract summary surfaced at Checkpoint 2.
type ToolContractItem struct {
	// Consumer agent ID followed by the compiler's tool ID (<agent_id>/<tool_id>).
	ID string
	// Compiler-selected toolset registration route.
	Toolset string
	// Tool name.
	Name string
	// Tool description.
	Description string
	// Generated provider model input before consumer binding.
	ArgsSchema string
	// Generated provider text-only input, when supported.
	TextOnlyArgsSchema *string
	// Compiled consumer input choices, when binding is declared.
	InputBinding *ToolInputBindingItem
	// Generated model-visible result schema; empty when the tool declares no
	// result.
	ReturnSchema string
	// Compiler-listed runtime or provider fields omitted from the provider model
	// input.
	InjectedFields []string
	// True when the tool requires a UI-capable runtime.
	RequiresUI bool
	// True when the tool declares a design-time Confirmation gate. This is a
	// declaration: it does not show that the application delivers the approval
	// request or continues after the answer.
	RequiresConfirmation bool
	// True when the tool declares a BoundedResult cursor/truncation contract.
	BoundedResult bool
}

// Compiled consumer input contracts declared for one selected tool. The
// application installs a binder and supplies values at runtime; compilation
// does not prove that wiring.
type ToolInputBindingItem struct {
	// Generated ordinary bound model input.
	ArgsSchema string
	// Generated ordinary text-only input, when supported.
	TextOnlyArgsSchema *string
	// Generated lookup-key input, when declared; application lookup values are not
	// inspected.
	LookupArgsSchema *string
	// Generated text-only lookup-key input, when supported.
	LookupTextOnlyArgsSchema *string
	// Compiler-listed fields supplied outside the ordinary bound model input.
	InjectedFields []string
}

// TraceList is the result type of the surla service list_traces method.
type TraceList struct {
	// Matching spans found in this page's bounded disk window.
	Spans []*TraceSpan
	// True when older records have not yet been examined.
	HasMore bool
	// Cursor to examine the next older window; present only when has_more is true.
	NextCursor *string
}

// Safe diagnostic details of one completed operation belonging to the
// authenticated caller. Raw errors, prompts, events, credentials, and
// filesystem paths are not included. OpenTelemetry export, when configured by
// the operator, retains the original spans.
type TraceSpan struct {
	// OpenTelemetry trace identifier.
	TraceID string
	// OpenTelemetry span identifier.
	SpanID string
	// Parent span identifier; empty when this span has no parent.
	ParentSpanID string
	// Operation name, at most 128 bytes.
	Name string
	// Operation start time in UTC.
	StartTime string
	// Operation finish time in UTC.
	EndTime string
	// Elapsed milliseconds.
	DurationMs int64
	// Original span status: unset, ok, or error. An unset status does not
	// establish success.
	Status string
	// Safe operation summary, at most 2048 bytes; never a raw error message.
	Summary string
	// Selected operation identifiers and results; at most six values of 1024 bytes
	// each.
	Attributes map[string]string
	// True when text was shortened to fit this diagnostic record; use operator
	// telemetry for the full values.
	Shortened bool
}

// Caller-authored OpenUI Lang decision view for exactly one Change Card
// revision. It is presentation only: it is never hashed into request_revision,
// confirm_intent never reads it, and it describes the card only while
// composed_for_revision equals the card's request_revision.
type UICompositionItem struct {
	// OpenUI Lang program from the analysis's ui_composition, exactly as the
	// caller sent it. The server does not check it; the checkpoint viewer
	// validates it and shows its error state, with the rest of the card still
	// usable, when the program is not a valid composition.
	Program string
	// request_revision of the Change Card this program was composed for.
	ComposedForRevision string
}

// Saved Checkpoint 5 promotion approval recorded on the Change Card whose
// current promotion inputs could not be verified on this read.
type UnverifiedApprovalItem struct {
	// Recorded promotion approval from the Change Card.
	Approval *ApprovalItem
	// Explanation of why the recorded approval could not be verified against
	// current promotion inputs and how to recover.
	Reason string
}

// UpdateDependenciesResult is the result type of the surla service
// update_dependencies method.
type UpdateDependenciesResult struct {
	// Operation identifier; pass it to read_check_output to read the full output.
	OpID string
	// Workspace-relative go.mod, go.sum and go.work.sum files whose bytes changed
	// and were written.
	FilesWritten []string
	// At most 16 KiB: what was updated, and Go's message for any module that could
	// not be.
	Message string
}

// One deterministic check of a repair scenario.
type VerificationCheck struct {
	// Check name.
	Name string
	// Whether the check passed.
	Passed bool
	// Why the check failed; empty when it passed.
	Diagnostic *string
}

// The run produced a verification report. Its verdict is report.passed.
type VerificationCompleted struct {
	// Evaluator suite the report was produced by.
	SuiteID string
	// Dependency profile the suite ran the candidate with, such as sim.
	Environment string
	// The builder view of the report.
	Report *BuilderVerificationReport
}

// Every declared scenario, counted by outcome.
type VerificationCounts struct {
	// Scenarios the suite declares.
	Required int
	// Scenarios that passed.
	Passed int
	// Scenarios whose checks failed.
	Failed int
	// Declared scenarios the suite did not report.
	NotRun int
	// Scenarios that could not be evaluated.
	HarnessError int
}

// VerificationListResult is the result type of the surla service
// list_verifications method.
type VerificationListResult struct {
	// Change Card identifier.
	ChangeID string
	// Verification runs for change_id in newest-first order.
	Runs []*VerificationStatusResult
}

// The run was accepted but did not complete: a step failed, or its processes
// ended or were canceled or timed out before it finished. The summary states
// where it stopped, without command output; full evidence, including any
// partial report saved while it was being stopped, stays with the evaluator.
type VerificationNotCompleted struct {
	// execution_failed when a step failed; interrupted when the run's process
	// ended before it finished.
	Kind string
	// Where the run stopped.
	Stage string
	// Builder-safe description of what stopped the run; never command output.
	Summary string
}

// The run is still building or evaluating the candidate.
type VerificationRunning struct {
	// When the run was accepted.
	StartedAt string
}

// One declared scenario as builders see it. Repair scenarios carry their name,
// checks and environment error; holdout scenarios appear only as holdout-<n>
// with their outcome.
type VerificationScenario struct {
	// Scenario name for a repair scenario, or holdout-<n> for a holdout.
	ID string
	// How the scenario ended.
	Outcome string
	// The repair scenario's checks; empty for holdouts.
	Checks []*VerificationCheck
	// The repair scenario's environment error; empty for holdouts.
	Error *string
}

// VerificationStatusResult is the result type of the surla service
// verify_change method.
type VerificationStatusResult struct {
	// Verification run identifier; get_verification takes it.
	RunID string
	// Change Card the run verifies.
	ChangeID string
	// Change Card revision the run verifies.
	RequestRevision string
	// Candidate commit the run builds and verifies.
	CandidateCommit string
	// Evaluator suite commit the operator configured for the run.
	SuiteCommit string
	// When the run was accepted.
	AcceptedAt string
	// Exactly one of running, completed or not_completed.
	State State
}

// VerifyChangePayload is the payload type of the surla service verify_change
// method.
type VerifyChangePayload struct {
	// Confirmed Change Card identifier.
	ChangeID string
	// Current request_revision of the confirmed Change Card.
	RequestRevision string
	// Full commit ID of the candidate to build and verify (40 or 64 lowercase hex
	// characters).
	CandidateCommit string
}

